-- auth s7@ilpi.demo
insert into auth.users (instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change) values ('00000000-0000-0000-0000-000000000000','aaaaaaaa-bbbb-cccc-dddd-000000000007'::uuid,'authenticated','authenticated','s7@ilpi.demo',crypt('ILPI-Demo-2026!', gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}'::jsonb,'{}'::jsonb,now(),now(),'','','','') on conflict (id) do nothing;
insert into auth.identities (id,user_id,identity_data,provider,provider_id,last_sign_in_at,created_at,updated_at) values ('aaaaaaaa-bbbb-cccc-dddd-000000000007'::uuid,'aaaaaaaa-bbbb-cccc-dddd-000000000007'::uuid, jsonb_build_object('sub','aaaaaaaa-bbbb-cccc-dddd-000000000007','email','s7@ilpi.demo'), 'email', 'aaaaaaaa-bbbb-cccc-dddd-000000000007', now(), now(), now()) on conflict do nothing;
update public.profissionais set user_id='aaaaaaaa-bbbb-cccc-dddd-000000000007'::uuid where id='s7';
